<?php
namespace App\Http\Controllers\Admin;
use App\Enums\TransactionStatus; use App\Enums\TransactionType; use App\Http\Controllers\Controller; use App\Models\Brand; use App\Models\CreditLedgerEntry; use App\Models\Transaction; use App\Services\Dashboard\DashboardService; use App\Services\Dashboard\DateRange; use App\Services\Transactions\CreditLedgerService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Response; use Illuminate\View\View;
class ReportController {
 private function filtered(Request $r){$range=DateRange::fromPreset($r->string('date','this_month')->toString(),$r->input('from'),$r->input('to'));$brandId=$r->filled('brand')&&$r->input('brand')!=='total'?$r->integer('brand'):null;$kind=$r->string('kind','all')->toString();$q=Transaction::with(['agent','brand','employee'])->where('status',TransactionStatus::Completed->value)->whereBetween('completed_at',[$range->start,$range->end]);if($brandId)$q->where('brand_id',$brandId);match($kind){'deposit'=>$q->where('type',TransactionType::PaidTopup->value),'credit'=>$q->where('type',TransactionType::Credit->value),'credit_repayment'=>$q->where('type',TransactionType::CreditRepayment->value),'withdrawal'=>$q->where('type',TransactionType::Withdrawal->value),'commission'=>$q->where('type',TransactionType::Commission->value),default=>null};return[$q,$range,$brandId,$kind];}
 public function index(Request $r,DashboardService $d,CreditLedgerService $credits):View{[$q,$range,$brandId,$kind]=$this->filtered($r);$outstanding=collect();if($kind==='credit'){$ids=\App\Models\Agent::query()->when($brandId,fn($x)=>$x->where('brand_id',$brandId))->pluck('id');$map=$credits->outstandingMap($ids);$outstanding=\App\Models\Agent::with('brand')->whereIn('id',array_keys(array_filter($map,fn($v)=>$v>0)))->get()->map(function($a)use($map){$a->outstanding_credit=$map[$a->id]??0;return $a;})->sortByDesc('outstanding_credit')->values();}return view('admin.reports.index',['transactions'=>$q->latest('completed_at')->paginate(50)->withQueryString(),'summary'=>$d->data($range,$brandId),'range'=>$range,'brandId'=>$brandId,'brands'=>Brand::orderBy('name')->get(),'preset'=>$r->string('date','this_month')->toString(),'kind'=>$kind,'outstandingCredits'=>$outstanding]);}
 public function export(Request $r){[$q]=$this->filtered($r);$rows=$q->latest('completed_at')->get();return Response::streamDownload(function()use($rows){$h=fopen('php://output','w');fputcsv($h,['Reference','Type','Brand','Agent ID','Username','Employee','Amount','Valid Payments','Risk','Completed']);foreach($rows as $t)fputcsv($h,[$t->reference,$t->type->value,$t->brand?->name,$t->agent?->agent_id,$t->agent?->username,$t->employee?->name,$t->amount,$t->valid_payment_total,$t->risk_level?->value,$t->completed_at?->toIso8601String()]);fclose($h);},'agent-audit-report.csv',['Content-Type'=>'text/csv']);}
}
